it("slices the precompressed variant when it is selected", async () => {
  const gz = "g".repeat(300);
  t.app.all("/gz/**", (event) =>
    serveStatic(event, {
      encodings: { gzip: ".gz" },
      getContents: (id) => (id.endsWith(".gz") ? gz : body),
      getMeta: (id) =>
        id.endsWith(".gz")
          ? { type: "text/plain", encoding: "gzip", size: 300 }
          : { type: "text/plain", size: 1000 },
    }),
  );

  const res = await t.fetch("/gz/file.txt", {
    headers: { range: "bytes=0-9", "accept-encoding": "gzip" },
  });
  expect(res.status).toBe(206);
  expect(res.headers.get("content-encoding")).toBe("gzip");
  expect(res.headers.get("content-range")).toBe("bytes 0-9/300");
  expect(await res.text()).toBe(gz.slice(0, 10));
});

